"""
Test that VCS dependencies still work after our fix.
"""

import tempfile
import os
from conda_devenv.devenv import load_yaml_dict

def test_vcs_dependencies():
    """Test that VCS dependencies still work correctly."""

    yaml_content = """
name: test_vcs
dependencies:
- pip:
  - git+https://github.com/user/repo.git@v1.0
  - hg+ssh://hg@bitbucket.org/user/repo@tip
  - regular_package>=1.0
"""

    with tempfile.NamedTemporaryFile(mode='w', suffix='.yml', delete=False) as f:
        f.write(yaml_content.strip())
        temp_filename = f.name

    try:
        # Load and process the YAML
        conda_yaml_dict, environment = load_yaml_dict(temp_filename)

        # Extract pip dependencies
        dependencies = conda_yaml_dict.get('dependencies', [])
        pip_deps = None
        for dep in dependencies:
            if isinstance(dep, dict) and 'pip' in dep:
                pip_deps = dep['pip']
                break

        print("VCS Dependencies Test:")
        print("YAML content:")
        print(yaml_content.strip())
        print(f"\nProcessed pip dependencies ({len(pip_deps) if pip_deps else 0}):")
        if pip_deps:
            for i, dep in enumerate(pip_deps):
                print(f"  {i+1}. {dep}")

        # VCS dependencies should be preserved as-is
        expected_vcs = [
            'git+https://github.com/user/repo.git@v1.0',
            'hg+ssh://hg@bitbucket.org/user/repo@tip'
        ]

        success = True
        for vcs_dep in expected_vcs:
            if vcs_dep not in pip_deps:
                print(f"❌ Missing VCS dependency: {vcs_dep}")
                success = False

        if success:
            print("✅ VCS dependencies correctly preserved")
        return success

    finally:
        # Clean up
        os.unlink(temp_filename)

def test_merge_with_vcs():
    """Test merging with VCS dependencies."""
    from conda_devenv.devenv import merge

    dict1 = {
        "dependencies": [
            {"pip": ["git+https://github.com/user/repo1.git@v1.0", "package1"]}
        ]
    }

    dict2 = {
        "dependencies": [
            {"pip": ["git+https://github.com/user/repo2.git@v2.0", "package2"]}
        ]
    }

    merged = merge([dict1, dict2])
    print("\nMerge with VCS test:")
    print("Merged result:", merged)

    # Extract pip deps
    pip_deps = None
    for dep in merged.get("dependencies", []):
        if isinstance(dep, dict) and "pip" in dep:
            pip_deps = dep["pip"]
            break

    if pip_deps and len(pip_deps) == 4:
        print("✅ VCS dependencies correctly merged")
        return True
    else:
        print(f"❌ VCS merge failed, got {len(pip_deps) if pip_deps else 0} deps")
        return False

if __name__ == "__main__":
    success1 = test_vcs_dependencies()
    success2 = test_merge_with_vcs()

    if success1 and success2:
        print("\n🎉 All VCS tests passed!")
    else:
        print("\n💥 Some VCS tests failed!")

    exit(0 if success1 and success2 else 1)"}
